from rcb_client import Robot
import numpy as np
r=Robot(); o=r.get_obs(depth=True,video='none'); d=o.last_depth['over_shoulder_left_camera']; im=o.last['over_shoulder_left_camera']
K=np.array(r.spec()['cameras']['over_shoulder_left_camera']['intrinsic_cv']); E=np.array(o.meta['cameras']['over_shoulder_left_camera']['extrinsic_cv']); R=E[:,:3]; t=E[:,3]
for label, us, vs in [('milk',range(600,681,10),range(440,541,10)),('oj',range(810,921,10),range(320,431,10))]:
 print('\n',label)
 for v in vs:
  out=[]
  for u in us:
   z=float(d[v,u]);
   if z:
    c=np.linalg.inv(K)@np.array([u*z,v*z,z]); w=np.linalg.inv(R)@(c-t)
    rgb=im[v,u]
    out.append(f'{u}:{w[0]:.2f},{w[1]:.2f},{w[2]:.2f}/{rgb[0]}')
   else: out.append(f'{u}:0')
  print(v,' '.join(out))
